119	+    public String text() {
120	+        BigDecimal issRetained = calculateIssRetained(total);
121	+        StringBuilder text = new StringBuilder();
122	+        text.append("Fatura de hospedagem nº ").append(reservationId).append('\n');
123	+        text.append("Empresa: ").append(companyName).append(" (CNPJ ").append(companyCnpj).append(")\n");
124	+        text.append("Hóspede: ").append(guestName).append('\n');
125	+        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
126	+        text.append("Entrada: ").append(TextFormat.datePtBr(checkIn))
127	+                .append(" | Saída: ").append(TextFormat.datePtBr(checkOut))
128	+                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
129	+        text.append("Diárias: ").append(TextFormat.moneyPtBr(subtotal)).append('\n');
130	+        text.append("Total: ").append(TextFormat.moneyPtBr(total)).append('\n');
131	+        text.append("ISS retido (5%): ").append(TextFormat.moneyPtBr(issRetained)).append('\n');
132	+        return text.toString();
133	+    }
134	+
135	+    private static BigDecimal calculateIssRetained(BigDecimal total) {
136	+        BigDecimal iss = total.multiply(new BigDecimal("0.05"));
137	+        return iss.setScale(2, java.math.RoundingMode.HALF_EVEN);
138	+    }
139	+}
