 88	import hotel.rooms.Room;
 89	import hotel.rooms.Rooms;
 90	import java.math.BigDecimal;
 91	
 92	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 93	public final class ReservationService {
 94	
 95	    static final String HOTEL_NAME = "Pousada Maré Alta";
 96	
 97	    private final Rooms rooms;
 98	    private final ReservationStore store;
 99	    private final PriceCalculator priceCalculator;
100	    private final EmailSender emailSender;
101	
102	    public ReservationService(
103	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
104	        this.rooms = rooms;
105	        this.store = store;
106	        this.priceCalculator = priceCalculator;
107	        this.emailSender = emailSender;
108	    }
109	
110	    public synchronized Reservation create(NewReservation request) {
111	        if (!request.checkOut().isAfter(request.checkIn())) {
112	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
113	        }
114	        if (request.guests() < 1) {
115	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
116	        }
117	        Room room = rooms.find(request.roomNumber())
118	                .orElseThrow(() -> new HotelException(
119	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
120	        if (request.guests() > room.capacity()) {
121	            throw new HotelException(
122	                    ErrorCode.CAPACITY_EXCEEDED,
123	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
124	        }
125	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
126	            throw new HotelException(
127	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
128	        }
129	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
130	        return store.add(request, price);
131	    }
132	
133	    public Reservation find(long reservationId) {
134	        return store.find(reservationId)
135	                .orElseThrow(() -> new HotelException(
136	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
137	    }
138	
139	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
140	    public synchronized Reservation confirm(long reservationId) {
141	        Reservation reservation = find(reservationId);
142	        if (reservation.status() != ReservationStatus.PENDING) {
143	            throw notAllowed(reservation, "confirm");
144	        }
145	        reservation.confirmPayment();
146	        store.update(reservation);
147	        Document document = generateDocument(reservation, roomOf(reservation));
148	        emailSender.send(
149	                reservation.guest().email(),
150	                "Reserva confirmada - " + HOTEL_NAME,
151	                confirmationEmailBody(reservation, document));
152	        return reservation;
153	    }
154	
155	    /**
156	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
157	     * reservation was never paid, so nothing comes back).
158	     */
159	    public synchronized Reservation cancel(long reservationId) {
160	        Reservation reservation = find(reservationId);
161	        if (reservation.status() != ReservationStatus.PENDING
162	                && reservation.status() != ReservationStatus.CONFIRMED) {
163	            throw notAllowed(reservation, "cancel");
164	        }
165	        BigDecimal refund = switch (reservation.ratePlan()) {
166	            case STANDARD -> reservation.amountPaid();
167	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
168	        };
169	        reservation.cancel(refund);
170	        store.update(reservation);
171	        return reservation;
172	    }
173	
174	    public synchronized Reservation checkIn(long reservationId) {
175	        Reservation reservation = find(reservationId);
176	        if (reservation.status() != ReservationStatus.CONFIRMED) {
177	            throw notAllowed(reservation, "check in");
178	        }
179	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
180	        store.update(reservation);
181	        return reservation;
182	    }
183	
184	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
185	    public synchronized Document checkOut(long reservationId) {
186	        Reservation reservation = find(reservationId);
187	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
188	            throw notAllowed(reservation, "check out");
189	        }
190	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
191	        store.update(reservation);
192	        return generateDocument(reservation, roomOf(reservation));
193	    }
194	
195	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
196	    public Document receiptCopy(long reservationId) {
197	        Reservation reservation = find(reservationId);
198	        if (!reservation.isPaid()) {
199	            throw notAllowed(reservation, "issue a receipt for");
200	        }
201	        return generateDocument(reservation, roomOf(reservation));
202	    }
203	
204	    private Document generateDocument(Reservation reservation, Room room) {
205	        Guest guest = reservation.guest();
206	        if (guest.companyCnpj() != null) {
207	            return new Invoice(reservation, room);
208	        } else if (guest.guestPassport() != null) {
209	            return new BookingReceipt(reservation, room);
210	        } else {
211	            return new ReservationReceipt(reservation, room);
212	        }
213	    }
214	
215	    private Room roomOf(Reservation reservation) {
216	        return rooms.find(reservation.roomNumber()).orElseThrow();
217	    }
218	
219	    private static String confirmationEmailBody(Reservation reservation, Document document) {
220	        return "Olá, " + reservation.guest().name() + "!\n\n"
221	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
222	                + document.text() + "\n"
223	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
224	                + "Até breve!\n";
225	    }
226	
227	    private static HotelException notAllowed(Reservation reservation, String operation) {
228	        return new HotelException(
229	                ErrorCode.OPERATION_NOT_ALLOWED,
230	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
231	    }
232	}
